def grandfather_existing_accounts(apps, schema_editor):
    """
    Accounts created before AUTH-02 (beta designers, early shoppers) count as confirmed,
    so nobody is suddenly blocked from checkout or their studio. Their phone numbers are
    also stored in the one +234 format, unless that would clash with another account.
    """
    from django.utils import timezone
    from apps.common.nigeria import normalize_phone

    User = apps.get_model('accounts', 'User')
    User.objects.filter(email_verified_at__isnull=True).update(email_verified_at=timezone.now())

    taken = set(User.objects.exclude(phone_number__isnull=True).values_list('phone_number', flat=True))
    for user in User.objects.exclude(phone_number__isnull=True).exclude(phone_number=''):
        normalized = normalize_phone(user.phone_number)
        if not normalized or normalized == user.phone_number or normalized in taken:
            continue
        taken.discard(user.phone_number)
        taken.add(normalized)
        user.phone_number = normalized
        user.save(update_fields=['phone_number'])


